 void Metric(FlowLayoutPanel p,string text,NumericUpDown n,int min,int max,int value){p.Controls.Add(new Label{Text=text,AutoSize=true,Margin=new Padding(0,9,4,0)});n.Minimum=min;n.Maximum=max;n.Value=value;n.Width=65;n.Margin=new Padding(0,5,12,5);p.Controls.Add(n);}
 FontPreset ReadPreset(){return new FontPreset{OverrideFont=overrideFont.Checked,Face=faces.Text.Trim(),Height=(int)height.Value,Width=(int)width.Value,Spacing=(int)spacing.Value,Bold=bold.Checked,Charset=charset.SelectedIndex==1?136:charset.SelectedIndex==2?134:charset.SelectedIndex==3?128:-1,Vk=keyVk,Modifiers=keyMods};}
 void LoadPreset(FontPreset p){updating=true;try{overrideFont.Checked=p.OverrideFont;faces.Text=p.Face;height.Value=p.Height;width.Value=p.Width;spacing.Value=p.Spacing;bold.Checked=p.Bold;charset.SelectedIndex=p.Charset==136?1:p.Charset==134?2:p.Charset==128?3:0;keyVk=p.Vk;keyMods=p.Modifiers;hotkey.Text=p.HotkeyText();}finally{updating=false;}UpdatePreview();}
 void UpdatePreview(){if(updating)return;try{var p=ReadPreset();p.Validate();preview.Preset=p;preview.Invalidate();summary.Text="字型："+(!p.OverrideFont?"保留漢化原字型":p.Face)+"   ·   "+p.HotkeyText()+"   ↗ 設定";}catch(Exception){}}
 void AutoPlacement(){try{string root=Path.GetDirectoryName(Path.GetFullPath(game.Text)),dir=Path.GetDirectoryName(Path.GetFullPath(patch.Text));placement.SelectedIndex=!string.Equals(root,dir,StringComparison.OrdinalIgnoreCase)&&dir.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase)?1:0;}catch{}}
 async Task AnalyzeGame(){
  if(running||!File.Exists(game.Text))return;string gp=Path.GetFullPath(game.Text);int token=++revision;analysis=null;analyzing=true;install.Enabled=false;state.Text="自動分析載入入口…";
  try{var a=await Task.Run(()=>Core.AnalyzeGame(gp));if(IsDisposed||token!=revision||!string.Equals(gp,Path.GetFullPath(game.Text),StringComparison.OrdinalIgnoreCase))return;analysis=a;hosts.Items.Clear();foreach(var c in a.Candidates)hosts.Items.Add(c);if(hosts.Items.Count>0)hosts.SelectedIndex=0;location.Text="遊戲目錄："+Path.GetDirectoryName(gp);LoadPreset(FontPreset.FromIni(Path.Combine(Path.GetDirectoryName(gp),"FontHook.ini")));if(File.Exists(Integration.Marker(gp))){var record=XDocument.Load(Integration.Marker(gp)).Root;string src=(string)record.Attribute("SourcePatch");if(src!=null)patch.Text=src;}
   if(string.IsNullOrWhiteSpace(patch.Text)){string root=Path.GetDirectoryName(gp);string[] options={Path.Combine(root,"winmm.dll"),Path.Combine(root,"dll","winmm.dll"),Path.Combine(root,"cn patch","winmm.dll")};foreach(string f in options){if(File.Exists(f)){string h=Core.Hash(f);if(h!="2007a498181e1c6f7d36600e5dbb5dcedfa01b9583b129b9136e56924d219684"&&h!="9e46b7532d8d029755cf702928b562f14d5afa403e1286b8ad49561cee5f8191"&&h!="454cfcb97a6da41a23fd566e0e3453cb90ce5ce01d293c3a316a186223fa17b7"&&!IsBundledFont(f,a)){patch.Text=f;break;}}}}
   WriteLog("自動分析完成："+Core.Arch(a.Game)+"，"+a.Candidates.Count+" 個候選入口。" );state.Text=a.Candidates.Count>0?"已就緒：選取原漢化 DLL 後安裝":"沒有已支援的載入入口";AutoPlacement();UpdateHelp();RefreshLoaded();
  }catch(Exception e){if(token==revision){state.Text="分析未完成";WriteLog(e.Message);}}finally{if(token==revision){analyzing=false;UpdateAvailability();}}
 }
 bool IsBundledFont(string file,Analysis a){using(var sha=System.Security.Cryptography.SHA256.Create()){string h=BitConverter.ToString(sha.ComputeHash(Integration.FontBinary(Core.Arch(a.Game)))).Replace("-","").ToLowerInvariant();return Core.Hash(file)==h;}}
 async Task InstallSelected(){
  if(analysis==null||hosts.SelectedItem==null)return;string gp=Path.GetFullPath(game.Text),pp=patch.Text;var c=(Candidate)hosts.SelectedItem;FontPreset p;bool upgrade=File.Exists(Integration.Marker(gp));
  try{p=ReadPreset();p.Validate();if(!upgrade)Core.BindPatch(analysis,pp);else pp=(string)XDocument.Load(Integration.Marker(gp)).Root.Attribute("SourcePatch")??pp;}catch(Exception e){WriteLog(e.Message);return;}
  string place=placement.SelectedIndex==2?"translation":placement.SelectedIndex==1?"patch":"root",mode=original.SelectedIndex==1?"delete":"bak";bool compatible=early.Checked;var a=analysis;
  string plan="安裝到："+Path.GetDirectoryName(gp)+"\n漢化主代理："+(place=="translation"?Path.Combine(Path.GetDirectoryName(gp),"漢化補丁"):place=="patch"?Path.GetDirectoryName(Path.GetFullPath(pp)):Path.GetDirectoryName(gp))+"\n字型："+(p.OverrideFont?p.Face:"保留漢化原字型")+" / "+p.HotkeyText()+"\n原漢化 DLL："+(mode=="delete"?"刪除，保留回復備份":"改為 .bak")+"\nPickerShowOnStartup=0";
  if(upgrade)plan+="\n將先還原上一版原件，再更新整合；失敗時恢復上一版。";
  if(MessageBox.Show(this,plan,"安裝確認",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return;
  await Run(()=>{string staging=Path.Combine(Path.GetDirectoryName(gp),".WinmmProxyMaker","builds");Integration.Upgrade(gp,()=>{Core.BindPatch(a,pp);string package=Core.Build(a,c,staging,compatible,WriteLog,place,mode,p);Integration.Install(package,WriteLog);},WriteLog);Ui(()=>{if(!preferences.Games.Contains(gp,StringComparer.OrdinalIgnoreCase))preferences.Games.Add(gp);preferences.Save();});});UpdateHelp();RefreshLoaded();
 }
 async Task RestoreSelected(){if(!File.Exists(game.Text))return;string marker=Integration.Marker(game.Text);if(!File.Exists(marker)){WriteLog("沒有安裝紀錄。");return;}await Run(()=>Integration.Restore(marker,WriteLog));UpdateAvailability();RefreshLoaded();}
 void UpdateAvailability(){bool exists=File.Exists(game.Text),installed=exists&&File.Exists(Integration.Marker(game.Text));install.Enabled=!running&&!analyzing&&analysis!=null&&hosts.Items.Count>0&&(File.Exists(patch.Text)||installed);install.Text=installed?"更新整合":"安裝到遊戲目錄";restore.Enabled=!running&&installed;if(running||!installed)applyCurrent.Enabled=false;distribute.Enabled=!running;}
 void RefreshLoaded(){if(!File.Exists(game.Text)){loadedState.Text="選擇遊戲以查看載入狀態";return;}string reason;bool ok=Integration.Loaded(game.Text,out reason);loadedState.Text=(ok?"✓ ":"○ ")+reason;applyCurrent.Enabled=ok&&!running;actualHotkey.Text="設定在下次啟動生效；實際快捷鍵會由遊戲內 SFH 顯示。";string trace=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(game.Text)),"FontHook.trace.log");try{if(File.Exists(trace)){string last=File.ReadLines(trace).Reverse().FirstOrDefault(l=>l.Contains("Registered configured hotkey")||l.Contains("Registered toggle hotkey"));if(last!=null)actualHotkey.Text="最近註冊："+last.Substring(last.IndexOf("[Picker]")+8);}}catch(IOException){}UpdateAvailability();}
 void UpdateHelp(){string dynamic="尚未選擇遊戲。";try{if(File.Exists(game.Text)){string root=Path.GetDirectoryName(Path.GetFullPath(game.Text)),marker=Integration.Marker(game.Text);dynamic="遊戲目錄\n"+root+"\n";if(File.Exists(marker)){var m=XDocument.Load(marker).Root;dynamic+="\n本次安裝檔案\n";foreach(var f in m.Elements("File")){string target=(string)f.Attribute("Target");if(target==null)continue;string n=Path.GetFileName(target);string role=n=="winmm.dll"?"SimpleFontHook":n=="FontHook.ini"?"字型與快捷鍵設定":n.StartsWith("translation_patch_")||n.StartsWith("wpm_payload_")?"原漢化補丁的獨立副本":"載入代理／橋接";string display=target.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase)?target.Substring(root.Length+1):target;dynamic+=display+"  →  "+role+((bool?)f.Attribute("Retired")==true?"（原件已移除）":"")+"\n";}}else dynamic+="\n預計入口："+(hosts.SelectedItem==null?"自動分析中":((Candidate)hosts.SelectedItem).Name)+"\n漢化主代理位置："+(placement.SelectedIndex==2?"漢化補丁資料夾":placement.SelectedIndex==1?"原漢化 DLL 的資料夾":"遊戲根目錄");}}
  catch(Exception e){dynamic=e.Message;}
  help.Text="檔案說明與操作指南\n\n"+dynamic+"\n\ntranslation_patch_<編號>.dll 是什麼？\n這是你選取的原漢化 DLL 的位元組副本。編號取自檔案雜湊，用來識別版本；原名 wpm_payload_<雜湊>.dll 也是同樣用途。代理載入它來執行漢化邏輯，請勿自行刪除或改名。\n\n為何子目錄方案還有根目錄 DLL？\n遊戲不會自動搜尋任意 DLL 資料夾。根目錄入口橋接會載入原補丁資料夾內的主代理，確保遊戲要求的介面可用；SimpleFontHook 保持在根目錄。\n\n所有設定、建置及回復資料在哪？\nFontHook.ini 在遊戲根目錄。建置紀錄、安裝清單與回復備份集中在遊戲內 .WinmmProxyMaker；沒有額外輸出資料夾需要選擇。\n\n如何分發字型設定？\n先啟動遊戲一次。主代理日誌確認漢化與字型 DLL 都成功載入後，字型頁可套用／分發設定；重新啟動遊戲後生效。預覽使用本機字型，無法驗證遊戲引擎或翻譯字元編碼。\n\n快捷鍵被占用？\n支援 Ctrl／Alt／Shift 組合。先嘗試設定的快捷鍵，失敗時回退 Insert、Pause、Scroll Lock。SFH 紀錄或視窗頁腳顯示實際選用鍵；若系統拒絕全部熱鍵，會記錄失敗；不會因此在啟動時彈出選單。\n\n要回復原狀？\n關閉遊戲後按「還原原 DLL」。原補丁和原字型設定都會還原；被你修改的產物不會被默默覆蓋。漢化的字型、腳本及資料檔仍需按原補丁要求放置。";
 }
 void DrawTab(object sender,DrawItemEventArgs e){Color bg=preferences.Dark?Color.FromArgb(18,26,39):Color.FromArgb(240,244,251),fg=preferences.Dark?Color.FromArgb(229,235,245):Color.FromArgb(35,49,72);using(var b=new SolidBrush(bg))e.Graphics.FillRectangle(b,e.Bounds);bool selected=e.Index==tabs.SelectedIndex;TextRenderer.DrawText(e.Graphics,tabs.TabPages[e.Index].Text,Font,e.Bounds,selected?Color.FromArgb(124,143,255):fg,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(selected)using(var p=new Pen(Color.FromArgb(115,132,250),3))e.Graphics.DrawLine(p,e.Bounds.Left+15,e.Bounds.Bottom-2,e.Bounds.Right-15,e.Bounds.Bottom-2);}
 void ApplyTheme(){bool dark=preferences.Dark;Color bg=dark?Color.FromArgb(15,22,34):Color.FromArgb(242,246,252),card=dark?Color.FromArgb(24,34,49):Color.White,fg=dark?Color.FromArgb(224,233,248):Color.FromArgb(33,47,70),muted=dark?Color.FromArgb(153,171,197):Color.FromArgb(103,119,145);Action<Control> apply=null;apply=c=>{c.ForeColor=(string)c.Tag=="muted"?muted:(string)c.Tag=="accent"?Color.FromArgb(117,172,246):fg;c.BackColor=(string)c.Tag=="card"?card:(c.Parent!=null?c.Parent.BackColor:bg);var b=c as ActionButton;if(b!=null){b.Dark=dark;b.Invalidate();}if(c is TextBox||c is ComboBox||c is NumericUpDown)c.BackColor=card;if(c is RichTextBox){c.BackColor=dark?Color.FromArgb(13,20,32):Color.White;c.ForeColor=fg;}foreach(Control child in c.Controls)apply(child);};apply(this);preview.Dark=dark;preview.Invalidate();themeToggle.Text=dark?"淺色":"暗色";if(IsHandleCreated)GuiBootstrap.FrameTheme(Handle,dark);tabs.Invalidate();}
 void ApplyMini(){logPanel.Visible=location.Visible=summary.Visible=advancedToggle.Visible=!preferences.Mini;if(preferences.Mini)advanced.Visible=false;miniToggle.Text=preferences.Mini?"完整":"Mini";MinimumSize=new Size(780,preferences.Mini?480:620);ClientSize=new Size(preferences.Mini?800:940,preferences.Mini?500:740);ClampForScreen();}
 public void SelectPage(int page){selectedView=page;for(int i=0;i<viewPanels.Count;i++){viewPanels[i].Visible=i==page;navButtons[i].Primary=i==page;navButtons[i].Invalidate();}if(page==2)UpdateHelp();}
 void StyleCombos(Control root){foreach(Control child in root.Controls){var box=child as ComboBox;if(box!=null){box.FlatStyle=FlatStyle.Flat;box.DrawMode=DrawMode.OwnerDrawFixed;box.DrawItem+=(s,e)=>{if(e.Bounds.Width<=0)return;bool selected=(e.State&DrawItemState.Selected)!=0&&(e.State&DrawItemState.ComboBoxEdit)==0;using(var brush=new SolidBrush(selected?Color.FromArgb(72,84,183):box.BackColor))e.Graphics.FillRectangle(brush,e.Bounds);string text=e.Index>=0?box.Items[e.Index].ToString():box.Text;TextRenderer.DrawText(e.Graphics,text,box.Font,e.Bounds,selected?Color.White:box.ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};}StyleCombos(child);}}
 void ClampForScreen(){var area=Screen.FromControl(this).WorkingArea;MinimumSize=new Size(Math.Min((int)(780*DeviceDpi/96f),area.Width-40),Math.Min((int)((preferences.Mini?480:620)*DeviceDpi/96f),area.Height-40));if(Height>area.Height-40)Height=area.Height-40;if(Width>area.Width-40)Width=area.Width-40;PerformLayout();}
 protected override void OnDpiChanged(DpiChangedEventArgs e){base.OnDpiChanged(e);ClampForScreen();}
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);GuiBootstrap.FrameTheme(Handle,preferences.Dark);}
 protected override void Dispose(bool disposing){if(disposing){debounce.Dispose();poll.Dispose();tabs.Dispose();}base.Dispose(disposing);}
 void Ui(Action f){if(IsDisposed)return;if(InvokeRequired)Invoke(f);else f();}
 void WriteLog(string s){Ui(()=>{log.AppendText(s+Environment.NewLine+Environment.NewLine);log.SelectionStart=log.TextLength;log.ScrollToCaret();});}
 async Task Run(Action f){running=true;foreach(Control c in inputs)c.Enabled=false;install.Enabled=false;restore.Enabled=false;applyCurrent.Enabled=false;distribute.Enabled=false;progress.Visible=true;state.Text="處理中…";try{await Task.Run(f);state.Text="完成";}catch(Exception e){state.Text="操作未完成，請查看記錄";WriteLog(e.Message);if(preferences.Mini)MessageBox.Show(this,e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{running=false;progress.Visible=false;foreach(Control c in inputs)c.Enabled=true;UpdateAvailability();}}
}
